const fmtInt   = n => (parseInt(n)||0).toLocaleString("it-IT");
const fmtShort = n => { n=parseInt(n)||0; return n>=1000 ? (n/1000).toFixed(1).replace(".0","")+"K" : String(n); };
const fmtDate  = d => d ? new Date(d).toLocaleDateString("it-IT",{day:"2-digit",month:"2-digit",year:"numeric"}) : "—";
const fmtDateTime = d => d ? new Date(d).toLocaleString("it-IT",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}) : "—";
const daysSince = d => d ? Math.floor((Date.now()-new Date(d).getTime())/86400000) : 0;
const agoLabel = d => { const n=daysSince(d); return n===0?"oggi":n===1?"ieri":n+" giorni fa"; };
const isEmail  = v => /^[^\s@]+@[^\s@]+\.[a-zA-Z]{2,}$/.test(String(v||"").trim());
const isUrl    = v => { if(!v) return true; try{ const u=new URL(String(v).trim()); return u.protocol==="http:"||u.protocol==="https:"; }catch(e){ return false; } };
const cleanHandle = v => String(v||"").trim().replace(/^@+/,"");

/**
 * Normalizza qualunque cosa scriva il candidato in { handle, url }.
 * Accetta @nome, nome, URL con o senza https, con o senza www, con o senza slash finali.
 * Se il valore non riconduce a un handle valido restituisce {handle:"", url:""}.
 */
const parseSocial = (raw, network) => {
  let s = String(raw||"").trim();
  if(!s) return { handle:"", url:"" };
  try{
    if(/^https?:\/\//i.test(s) || /^(www\.)?(instagram|tiktok)\.com/i.test(s)){
      if(!/^https?:\/\//i.test(s)) s = "https://" + s;
      const u = new URL(s);
      const first = u.pathname.split("/").filter(Boolean)[0] || "";
      s = first.replace(/^@+/,"");
    }
  }catch(e){ /* non è un URL, va bene */ }
  const h = s.replace(/^@+/,"").replace(/[^A-Za-z0-9._]/g,"");
  if(!h) return { handle:"", url:"" };
  const url = network==="tiktok"
    ? "https://www.tiktok.com/@"+h
    : "https://www.instagram.com/"+h+"/";
  return { handle:h, url:url };
};

/** Sfugge < > & per non spezzare Telegram in HTML mode. */
const escTg = v => String(v==null?"":v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");

/**
 * Converte un valore letto dallo screenshot in numero intero.
 * Gestisce: 3.648 · 3,648 · 1.234.567 · +5 · -3 · 1,2K · 3,6 Mln
 */
const toNum = (raw) => {
  // Mancante o non numerico → null, mai zero: un valore inventato non deve risultare letto.
  if(raw===null || raw===undefined) return null;
  if(typeof raw==="number") return Number.isFinite(raw) ? Math.round(raw) : null;
  if(typeof raw!=="string") return null;
  let s = raw.trim().toLowerCase().replace(/\s+/g,"");
  if(!s) return null;
  // Solo cifre, separatori, segno e suffissi (mila, k, mln, mio, m): "—", "n/d" o altro testo non sono numeri.
  if(!/^[+-]?[0-9][0-9.,]*(mln|mio|mila|k|m)?$/.test(s)) return null;
  const sign = s.charAt(0)==="-" ? -1 : 1;
  s = s.replace(/^[+-]/,"");
  let mult = 1;
  if(/(mln|mio|m)$/.test(s)){ mult = 1e6; s = s.replace(/(mln|mio|m)$/,""); }
  else if(/(mila|k)$/.test(s)){ mult = 1e3; s = s.replace(/(mila|k)$/,""); }
  s = s.replace(/[^0-9.,]/g,"");
  if(!s) return null;
  let value;
  if(mult>1){
    value = parseFloat(s.replace(",",".")) || 0;
  }else{
    const parts = s.split(/[.,]/);
    if(parts.length===1) value = parseFloat(parts[0]) || 0;
    else if(parts[parts.length-1].length===3) value = parseFloat(parts.join("")) || 0;
    else if(parts.length===2) value = parseFloat(parts[0]+"."+parts[1]) || 0;
    else value = parseFloat(parts.join("")) || 0;
  }
  return Math.round(sign * value * mult);
};

/**
 * Unisce i dati letti da due screenshot.
 * - Ogni campo è null quando non è visibile: null non sovrascrive un numero valido.
 * - Se entrambi gli screenshot forniscono un valore, si tiene quello del primo
 *   e si segnala il conflitto per una verifica manuale.
 * - Nessun campo viene sommato: le due immagini mostrano finestre diverse dello stesso dato.
 */
/**
 * Unisce i dati letti da due screenshot con logica di priorità:
 * 1. Un valore "complete" ha la precedenza su uno "partial"
 * 2. Se il valore più corto è l'inizio o la fine del più lungo → lettura parziale, usa il più lungo
 * 3. Se entrambi sono "complete" e diversi → vero conflitto, segnalato all'utente
 * 4. null non sovrascrive mai un numero valido
 */
const mergeInsights = (a, b) => {
  // Regola principale: vince sempre il valore proveniente dal box completamente visibile.
  // Un box tagliato/incerto non deve mai sovrascrivere un valore già completo,
  // né generare una falsa discrepanza: viene semplicemente ignorato per quel dato.
  // Una discrepanza viene segnalata SOLO quando entrambi gli screenshot mostrano
  // lo stesso box come completamente visibile ma con valori diversi.
  a = a || {}; b = b || {};
  const merged = {};
  const conflicts = [];
  const KEYS = ["views","netFollowers","interactions","accountsReached"];

  KEYS.forEach(k => {
    const fa = a[k] || { value:null, visibility:"not_visible" };
    const fb = b[k] || { value:null, visibility:"not_visible" };
    const va = fa.value, vb = fb.value;
    const completeA = fa.visibility === "complete" && va !== null && va !== undefined;
    const completeB = fb.visibility === "complete" && vb !== null && vb !== undefined;

    if(completeA && completeB){
      if(Number(va) === Number(vb)){
        // Stesso dato, box completo in entrambi gli screenshot: nessun problema.
        merged[k] = fa;
      } else {
        // Vero conflitto: entrambi i box sono interi ma il valore letto è diverso.
        merged[k] = fa;
        conflicts.push({ key:k, valueA:va, valueB:vb });
      }
    } else if(completeA && !completeB){
      // Il secondo screenshot ha il box tagliato per questo dato: si ignora,
      // il valore completo del primo resta valido così com'è.
      merged[k] = fa;
    } else if(!completeA && completeB){
      // Nel secondo screenshot il box è finalmente visibile per intero: lo adottiamo.
      merged[k] = fb;
    } else {
      // Nessuno dei due box è completamente visibile per questo dato:
      // se disponibile teniamo un valore di riferimento, ma resta uncertain/missing.
      if(va !== null && va !== undefined) merged[k] = fa;
      else if(vb !== null && vb !== undefined) merged[k] = fb;
      else merged[k] = { value:null, visibility:"not_visible" };
    }
  });

  return { merged, conflicts };
};

const readFileAsDataURL = file => new Promise((resolve,reject)=>{
  const r = new FileReader();
  r.onload  = e => resolve(e.target.result);
  r.onerror = () => reject(new Error("Impossibile leggere il file."));
  r.readAsDataURL(file);
});

/**
 * Ridimensiona e comprime lo screenshot prima del salvataggio.
 * Senza questo passaggio un'immagine da telefono supera il limite di 1 MiB
 * previsto da Firestore per singolo documento e il salvataggio viene rifiutato.
 * maxChars abbassa il limite solo quando serve (somma degli screenshot). Soglie di leggibilità effettive:
 * qualità JPEG mai sotto IMG_MIN_QUALITY e larghezza mai sotto IMG_MIN_WIDTH (le immagini già più strette
 * non vengono rimpicciolite). Se il limite non si raggiunge entro queste soglie, l'immagine è rifiutata.
 */
const IMG_QUALITY_STEPS = [0.82, 0.72, 0.62, 0.52, 0.42, 0.32];
const IMG_MIN_QUALITY = IMG_QUALITY_STEPS[IMG_QUALITY_STEPS.length - 1];
const IMG_MIN_WIDTH = 640;
const compressImageDetailed = (dataUrl, maxChars = MAX_STORED_BYTES) => new Promise((resolve,reject)=>{
  const img = new Image();
  img.onerror = () => reject(new Error("Immagine non valida."));
  img.onload  = () => {
    const ow = img.naturalWidth, oh = img.naturalHeight;
    if(!ow || !oh) return reject(new Error("Immagine non valida."));
    const minWidth = Math.min(IMG_MIN_WIDTH, ow);
    let w = Math.round(ow * (ow > IMG_MAX_WIDTH ? IMG_MAX_WIDTH/ow : 1));
    const height = cw => Math.max(1, Math.round(oh * cw / ow));
    const draw = (cw,q) => {
      const c = document.createElement("canvas");
      c.width = cw; c.height = height(cw);
      const ctx = c.getContext("2d");
      ctx.fillStyle = "#0E0E0E"; ctx.fillRect(0,0,c.width,c.height);
      ctx.drawImage(img,0,0,c.width,c.height);
      return c.toDataURL("image/jpeg", q);
    };
    let qi = 0, out = draw(w, IMG_QUALITY_STEPS[qi]);
    while(out.length > maxChars && qi < IMG_QUALITY_STEPS.length - 1){ qi++; out = draw(w, IMG_QUALITY_STEPS[qi]); }
    while(out.length > maxChars && w > minWidth){
      w = Math.max(minWidth, Math.round(w*0.85)); out = draw(w, IMG_QUALITY_STEPS[qi]);
    }
    if(out.length > maxChars) return reject(new Error("Immagine troppo grande: riprova con uno screenshot più leggero."));
    resolve({ dataUrl:out, width:w, height:height(w), quality:IMG_QUALITY_STEPS[qi] });
  };
  img.src = dataUrl;
});
const compressImage = (dataUrl, maxChars = MAX_STORED_BYTES) => compressImageDetailed(dataUrl, maxChars).then(r => r.dataUrl);

/**
 * Riporta gli screenshot entro il limite complessivo del Worker, ricomprimendo dal file originale
 * soltanto quelli più pesanti della quota media e soltanto se la somma supera il limite.
 * slots: [{ key, data, file }]. Restituisce { ok, data:{ key: nuovoDataUrl } } con le sole immagini cambiate.
 */
const fitScreenshotsToLimit = async (slots, limit = MAX_TOTAL_SCREENSHOTS) => {
  const present = slots.filter(s => s.data).map(s => ({ ...s }));
  const total = () => present.reduce((n, s) => n + s.data.length, 0);
  const data = {};
  if(total() <= limit) return { ok:true, data };
  const share = Math.floor(limit / present.length) - 2000;   // margine per gli arrotondamenti della codifica
  for(const s of present.filter(s => s.data.length > share).sort((a, b) => b.data.length - a.data.length)){
    if(!s.file) continue;
    try{ s.data = await compressImage(await readFileAsDataURL(s.file), share); data[s.key] = s.data; }
    catch(e){ return { ok:false, data:{} }; }
    if(total() <= limit) break;
  }
  return { ok: total() <= limit, data: total() <= limit ? data : {} };
};

/* ============================================================================
   7. COMPONENTI CONDIVISI
   ========================================================================== */
function Logo({height=26, style={}}){
  return <img src={BRAND.logoSrc} alt="EVORΛ" style={{height, width:"auto", display:"block", ...style}}/>;
}

function Badge({children, color="var(--red)", filled=false}){
  return (
    <span className="badge" style={{
      color: filled ? "#fff" : color,
      borderColor: filled ? color : color+"66",
      background: filled ? color : color+"1F"
    }}>{children}</span>
  );
}

function Tip({text}){
  return <span className="tip" title={text} aria-label={text}>i</span>;
}

function Field({label, required, hint, error, htmlFor, children}){
  return (
    <div className="field">
      <label className="field-label" htmlFor={htmlFor}>
        {label}{required && <span className="field-req"> *</span>}
      </label>
      {children}
      {hint && !error && <span className="field-hint">{hint}</span>}
      {error && <span className="field-err" role="alert">{error}</span>}
    </div>
  );
}

function ChipGroup({options, value, onChange, name}){
  return (
    <div className="chips" role="radiogroup" aria-label={name}>
      {options.map(o=>(
        <button type="button" key={o.v} role="radio" aria-checked={value===o.v}
          className={"chip"+(value===o.v?" chip-on":"")}
          onClick={()=>onChange(o.v)}>{o.l}</button>
      ))}
    </div>
  );
}

// value null: punteggio non calcolabile, mostrato come "—" e mai come zero.
function ScoreRing({value=0, color="var(--red)", size=52, label="SCORE"}){
  const r=(size/2)-4, c=2*Math.PI*r, dash=value===null ? 0 : c*(Math.max(0,Math.min(100,value))/100);
  return (
    <div style={{position:"relative",width:size,height:size,flexShrink:0}}>
      <svg width={size} height={size} style={{transform:"rotate(-90deg)"}} aria-hidden="true">
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke="var(--brd)" strokeWidth="3"/>
        <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color} strokeWidth="3"
          strokeDasharray={dash+" "+c} strokeLinecap="round"/>
      </svg>
      <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center"}}>
        <span style={{fontFamily:"var(--fh)",fontWeight:800,fontSize:size*.30,color,lineHeight:1}}>{value===null ? "—" : value}</span>
        {size>=48 && <span style={{fontFamily:"var(--fh)",fontSize:size*.13,color,opacity:.55,letterSpacing:".06em"}}>{label}</span>}
      </div>
    </div>
  );
}

function Spinner({label}){
  return (
    <div className="status-box">
      <div className="spinner"/>
      <div className="body-sm" style={{color:"var(--t2)"}}>{label}</div>
    </div>
  );
}


